pub fn finish(&mut self) -> io::Result<()> {
    self.finish_requested = true;
    loop {
        self.write_from_offset()?;
        if self.finished {
            return Ok(());
        }
        self.finish_step()?;
    }
}
```

where `finish_step` is extracted:

```rust
fn finish_step(&mut self) -> io::Result<()> {
    let finished_frame = self.finished_frame;
    let hint = self.with_buffer(|dst, op| op.finish(dst, finished_frame));
    self.offset = 0;
    let hint = hint?;
    if hint != 0 && self.buffer.is_empty() {
        return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "incomplete frame"));
