fn flush(&mut self) -> io::Result<()> {
    let mut finished = self.finished;
    loop {
        // If the output is blocked or has an error, return now.
        self.write_from_offset()?;

        if finished {
            break;
        }

        let hint = self.with_buffer(|dst, op| op.flush(dst));

        self.offset = 0;
        let hint = hint?;

        finished = hint == 0;
    }

    self.writer.flush()
}

